"""Run the game or a reproducible headless growth simulation."""
# title: Skill Seekers!!~深淵のアムリタ~
# desc: 4人パーティのスキル消耗・閃き・帰還を検証する開発中プロトタイプ
# license: TBD
import argparse
import json

from rpg.battle import Session
from rpg.content import load_content


def simulate(session, count):
    for _ in range(count):
        battle = session.next_battle()
        while not battle.outcome:
            battle.begin_round(battle.auto_actions())
            while battle.queue:
                battle.step()
        session.settle()
        # Headless runs have no selection UI; explicitly keep existing skills.
        for actor_index in session.pending_replacements:
            session.resolve_replacement(actor_index)
    return {
        "battles": session.completed, "wins": session.wins,
        "losses": session.losses, "draws": session.draws, "debug": session.debug,
        "party": [{"name": c.name, "type": c.growth_type, "HP": c.max_hp,
                   "STR": c.strength, "AGI": c.agility, "INT": c.intellect,
                   "skills": [session.skills[s].name for s in c.skills],
                   "skill_uses": {s: {"current": c.skill_uses[s], "max": c.max_uses(session.skills[s])} for s in c.skills},
                   "history": c.history} for c in session.party],
    }


def main():
    parser = argparse.ArgumentParser(description="SPARK / a tiny growth laboratory")
    parser.add_argument("--seed", type=int, help="Reproducible random seed")
    parser.add_argument("--simulate", type=int, metavar="N", help="Play N battles without a window")
    parser.add_argument("--debug", action="store_true", help="Start with boosted spark chance")
    parser.add_argument("--battle-lab", action="store_true", help="Original endless battle lab (full recovery between battles)")
    args = parser.parse_args()
    if args.simulate is not None and args.simulate < 1:
        parser.error("--simulate must be positive")
    try:
        session = Session(*load_content(), seed=args.seed)
    except (OSError, ValueError, KeyError, TypeError) as error:
        parser.exit(1, f"Data error: {error}\nCheck data/*.json (see README.md).\n")
    session.debug = args.debug
    if args.simulate:
        print(json.dumps(simulate(session, args.simulate), indent=2, ensure_ascii=False))
    else:
        if args.battle_lab:
            from rpg.app import App
        else:
            from rpg.dungeon_app import DungeonApp as App
        try:
            App(session)
        except (OSError, ValueError, KeyError, TypeError) as error:
            parser.exit(1, f"Resource/data error: {error}\nCheck game.pyxres, area2.pyxres, area3.pyxres and data/dungeon.json.\n")


if __name__ == "__main__":
    main()

sources.rpg/app.py:
"""160x120 UI. All rules live outside this module."""
from collections import deque
import time
from .statuses import active_statuses, clear_statuses
from .skill_targets import AUTO_TARGETS

import pyxel

from .art import load_art
from .models import Action
from .labels import TYPES, RARITIES, TARGETS, OUTCOMES, EFFECTS, CURRENCY_NAME
from .text import text, wrap_lines, font
from .sound import init_sound, play_cue, start_battle_music, stop_battle_music, play_victory_music, music_is_playing
from .growth import growth_bonus
from .keyboard import GameKeyboard
from .opening import GAME_TITLE
from .final_battle import AMRITA_ITEM_ID, LORD_OF_ELYSION_ID
from .final_presentation import FinalPresentation, AMRITA_MESSAGE_FRAME
from .battle_presentation import (BattlePresentation, result_pages, draw_status_icons, draw_battle_background,
                                  enemy_position, ASSET_BANK, KO_SPRITE_U, KO_SPRITE_V,
                                  KO_SPRITE_W, KO_SPRITE_H)


# The official Web touch pad emits gamepad buttons, not keyboard keys.
GAMEPAD_KEYS = {
    pyxel.KEY_UP: pyxel.GAMEPAD1_BUTTON_DPAD_UP,
    pyxel.KEY_DOWN: pyxel.GAMEPAD1_BUTTON_DPAD_DOWN,
    pyxel.KEY_LEFT: pyxel.GAMEPAD1_BUTTON_DPAD_LEFT,
    pyxel.KEY_RIGHT: pyxel.GAMEPAD1_BUTTON_DPAD_RIGHT,
    pyxel.KEY_Z: pyxel.GAMEPAD1_BUTTON_A,
    pyxel.KEY_X: pyxel.GAMEPAD1_BUTTON_B,
}

FANFARE_MAX_WAIT_SECONDS = 4.5
FANFARE_MAX_WAIT_FRAMES = 150
FANFARE_PRESENTATION_SECONDS = 2.4  # Existing score duration; no channel polling.
FANFARE_PRESENTATION_FRAMES = 72
QUIT_SELECT_HOLD_SECONDS = 1.0


class App:
    def __init__(self, session, run=True, headless=False, battle_on_start=True):
        self.session = session
        pyxel.init(160, 120, title=GAME_TITLE, fps=30,
                   display_scale=5, quit_key=pyxel.KEY_NONE, headless=headless)
        self.keyboard = GameKeyboard(enabled=not headless)
        self.quit_select_started_at = None
        self.keyboard.update()
        load_art(pyxel)
        font()
        self.audio = init_sound()
        self.overlay = None
        self.info_character = self.info_tab = self.scroll = 0
        self.result_page = 0
        self.notice = ""
        self.notice_timer = 0
        self.replacement_cursor = 0
        self.replacement_confirm = False
        self.debug_return_state = None
        self.debug_return_overlay = "debug_skills"
        self.debug_cursor = 0
        self.shake_timer = 0
        self.fanfare_started_at = None
        self.fanfare_start_frame = None
        self.fanfare_timed_out = False
        self.debug_events = []
        self.final_presentation = None
        self.battle_presentation = None
        if battle_on_start:
            self.start_battle()
        if run:
            pyxel.run(self.update, self.draw)

    def start_battle(self):
        self.final_presentation = None
        self.notice_timer = 0
        self.fanfare_started_at = None
        self.fanfare_start_frame = None
        self.battle = self.session.next_battle()
        self.log = ["新たな敵が現れた", "4人の行動を選ぼう"]
        self.pending = deque()
        self.begin_input()
        start_battle_music()

    def finish_results(self):
        if self.waiting_for_fanfare():
            return
        stop_battle_music()
        self.trace("NEXT BATTLE")
        self.start_battle()

    def waiting_for_fanfare(self):
        if self.battle.outcome != "VICTORY" or self.fanfare_started_at is None:
            return False
        elapsed = time.monotonic() - self.fanfare_started_at
        frames = pyxel.frame_count - self.fanfare_start_frame
        ticks = getattr(self, 'fanfare_visual_frames', 0)
        if (elapsed >= FANFARE_PRESENTATION_SECONDS or frames >= FANFARE_PRESENTATION_FRAMES or
            ticks >= FANFARE_PRESENTATION_FRAMES):
            if not self.fanfare_timed_out:
                self.fanfare_timed_out = elapsed >= FANFARE_MAX_WAIT_SECONDS or frames >= FANFARE_MAX_WAIT_FRAMES
                self.trace("VICTORY PRESENTATION END")
                stop_battle_music()
            self.fanfare_started_at = None
            return False
        return True

    def trace(self, event):
        if self.session.debug:
            message = f"[SPARK] {event} state={self.state} battle={self.session.completed}"
            self.debug_events.append(message)
            self.debug_events = self.debug_events[-40:]
            print(message)

    def audio_state(self):
        try:
            import js
            return str(js.window.sparkAudioState()).upper()
        except Exception:
            return "N/A"

    def next_result_label(self):
        return "次の戦闘"

    def begin_input(self):
        self.state = "command"
        self.actions = []
        self.order = [i for i, c in enumerate(self.session.party) if c.alive]
        self.actor_position = 0
        self.cursor = self.skill_cursor = self.target_cursor = 0
        self.selected_skill = None
        self.selected_item = None
        self.item_cursor = 0
        self.skip_confused_commands()
        if self.actor_position >= len(self.order) and self.order:
            self.battle.begin_round(self.actions)
            self.state, self.delay = 'resolve', 0
            self.log = [f'第{self.battle.round}ターン']

    def skip_confused_commands(self):
        while self.actor_position < len(self.order):
            index = self.order[self.actor_position]
            if 'confusion' not in active_statuses(self.session.party[index]):
                break
            self.actions.append(Action(index, 'STATUS'))
            self.actor_position += 1

    @property
    def actor_index(self):
        return self.order[min(self.actor_position, len(self.order) - 1)]

    @property
    def actor(self):
        return self.session.party[self.actor_index]

    def pressed(self, *keys):
        return any(self.button_pressed(key) for key in keys)

    def confirm(self):
        return self.pressed(pyxel.KEY_Z, pyxel.KEY_RETURN, pyxel.KEY_SPACE)

    def cancel(self):
        return self.pressed(pyxel.KEY_X, pyxel.KEY_ESCAPE)

    def confirm_held(self):
        return pyxel.btn(pyxel.KEY_Z) or pyxel.btn(pyxel.GAMEPAD1_BUTTON_A)

    def button_pressed(self, key, hold=0, repeat=0):
        return pyxel.btnp(key, hold, repeat) or (
            key in GAMEPAD_KEYS and pyxel.btnp(GAMEPAD_KEYS[key], hold, repeat))

    def direction(self, horizontal=False):
        low, high = (pyxel.KEY_LEFT, pyxel.KEY_RIGHT) if horizontal else (pyxel.KEY_UP, pyxel.KEY_DOWN)
        return int(self.button_pressed(high, 10, 3)) - int(self.button_pressed(low, 10, 3))

    def handle_quit_input(self):
        """Exit without saving; leave plumOS SELECT + D-pad shortcuts usable."""
        if self.pressed(pyxel.KEY_Q):
            pyxel.quit()
            return True
        dpad = (pyxel.GAMEPAD1_BUTTON_DPAD_UP, pyxel.GAMEPAD1_BUTTON_DPAD_DOWN,
                pyxel.GAMEPAD1_BUTTON_DPAD_LEFT, pyxel.GAMEPAD1_BUTTON_DPAD_RIGHT)
        if pyxel.btn(pyxel.GAMEPAD1_BUTTON_BACK) and not any(pyxel.btn(key) for key in dpad):
            now = time.monotonic()
            started = getattr(self, "quit_select_started_at", None)
            if started is None:
                self.quit_select_started_at = now
            elif now - started >= QUIT_SELECT_HOLD_SECONDS:
                pyxel.quit()
                return True
        else:
            self.quit_select_started_at = None
        return False

    def tell(self, message):
        self.notice, self.notice_timer = message, 60

    def targets(self):
        if self.selected_item or (self.selected_skill and self.selected_skill.target == "ally"):
            dead = self.selected_item == "PHOENIX ASH" or (self.selected_skill and self.selected_skill.effect == "revive")
            return [(i, target) for i, target in enumerate(self.session.party)
                    if target.alive != bool(dead) and
                    (self.selected_item != "POTION" or target.hp < target.max_hp) and
                    (self.selected_item != 'REMEDY' or active_statuses(target))]
        return [(i, target) for i, target in enumerate(self.battle.enemies) if target.alive]

    def battle_items(self):
        reserved = {item: sum(a.kind == "ITEM" and a.item_id == item for a in self.actions)
                    for item in ("POTION", "PHOENIX ASH", "REMEDY")}
        options = [item for item in reserved if self.session.inventory.counts[item] > reserved[item]
                   and (item != 'REMEDY' or any(c.alive and active_statuses(c) for c in self.session.party))]
        if self.battle.can_use_amrita and not any(a.item_id == AMRITA_ITEM_ID for a in self.actions):
            options.append(AMRITA_ITEM_ID)
        return options

    def commit(self, action):
        self.actions.append(action)
        self.actor_position += 1
        self.skip_confused_commands()
        self.cursor = self.skill_cursor = self.target_cursor = 0
        self.selected_skill = None
        self.selected_item = None
        if self.actor_position >= len(self.order):
            self.battle.begin_round(self.actions)
            self.state, self.delay = "resolve", 0
            self.log = [f"第{self.battle.round}ターン"]
        else:
            self.state = "command"

    def update_status_debug(self, confirm, cancel):
        units = self.session.party + self.battle.enemies
        self.status_debug_target = (self.status_debug_target + self.direction()) % len(units)
        self.status_debug_cursor = (self.status_debug_cursor + self.direction(horizontal=True)) % 5
        if cancel:
            self.overlay = None
            self.begin_input()
        elif confirm:
            from .statuses import STATUS_IDS
            target = units[self.status_debug_target]
            if self.status_debug_cursor == 4:
                clear_statuses(target)
                self.tell('DEBUG: 状態異常を解除')
            else:
                ident = STATUS_IDS[self.status_debug_cursor]
                applied = self.battle.apply_status(target, ident)
                self.tell('DEBUG: 付与' if applied else 'DEBUG: 付与失敗（KO/制御状態/耐性）')

    def draw_status_debug(self):
        from .statuses import STATUS_IDS
        units = self.session.party + self.battle.enemies
        unit = units[self.status_debug_target]
        self.title('DEBUG / 状態異常')
        text(5, 17, unit.name, 3, 36)
        names = [self.battle.status_definitions[k].name for k in STATUS_IDS] + ['解除']
        text(5, 32, ' / '.join(names), 2, 36)
        text(5, 44, '> ' + names[self.status_debug_cursor], 3, 36)
        for i, (ident, turns) in enumerate(active_statuses(unit).items()):
            text(5, 61 + i * 12, f'{self.battle.status_definitions[ident].name} 残{turns}T', 3, 36)
        self.footer('上下:対象 左右:種類 A:付与 B:戻る')

    def update(self):
        self.keyboard.update()
        if self.handle_quit_input():
            return
        if self.update_rescue_notice():
            return
        if self.state == 'amrita_effect':
            self.update_amrita_effect()
            return
        if self.state == 'resolve' and self.battle_visual().active:
            self.update_battle_visual()
            return
        self.shake_timer = max(0, self.shake_timer - 1)
        self.notice_timer = max(0, self.notice_timer - 1)
        if self.pressed(pyxel.KEY_F9):
            self.session.debug = not self.session.debug
            self.tell("DEBUG オン" if self.session.debug else "DEBUG オフ")
            if not self.session.debug and self.overlay == "debug_skills":
                self.overlay = None
            return
        if self.pressed(pyxel.KEY_F12):
            if self.session.debug and self.state in ("camp", "explore", "result") and not self.session.pending_replacements:
                self.overlay = None if self.overlay == "debug_skills" else "debug_skills"
                self.notice_timer = 0
            return
        if self.pressed(pyxel.KEY_D, pyxel.KEY_TAB):
            self.overlay = None if self.overlay == "info" else "info"
            self.scroll = 0
            return
        if self.pressed(pyxel.KEY_H):
            self.overlay = None if self.overlay == "help" else "help"
            return
        confirm, cancel = self.confirm(), self.cancel()
        if self.overlay == 'status_debug':
            self.update_status_debug(confirm, cancel)
            return
        if self.session.debug and self.state == 'command' and self.pressed(pyxel.KEY_F2):
            self.overlay = 'status_debug'
            self.status_debug_target = self.status_debug_cursor = 0
            return
        if self.overlay:
            if cancel:
                self.overlay = None
            elif self.overlay == "debug_skills":
                self.update_debug_skills(confirm)
            elif self.overlay == "info":
                move = self.direction(horizontal=True)
                if move:
                    self.info_character = (self.info_character + move) % 4
                    self.scroll = 0
                if confirm:
                    self.info_tab = (self.info_tab + 1) % 3
                    self.scroll = 0
                else:
                    self.scroll = max(0, min(self.info_scroll_limit(), self.scroll + self.direction()))
            return
        if self.state == "replace":
            self.update_replacement(confirm, cancel)
            return
        if self.state == "result":
            self.fanfare_visual_frames = getattr(self, 'fanfare_visual_frames', 0) + 1
            page_count = max(1, (len(self.result_lines) + 8) // 9)
            self.result_page = max(0, min(page_count - 1, self.result_page + self.direction(horizontal=True) + self.direction()))
            if confirm:
                if self.result_page + 1 < page_count:
                    self.result_page += 1
                else:
                    if self.waiting_for_fanfare():
                        return
                    if self.session.pending_replacements:
                        self.notice_timer = 0
                        self.state = "replace"
                        self.trace("REPLACEMENT")
                        self.replacement_cursor = 0
                        self.replacement_confirm = False
                    else:
                        self.finish_results()
            return
        if self.state == "resolve":
            self.delay -= 1
            if self.delay > 0 and not confirm and not self.confirm_held():
                return
            if self.pending:
                self.log.append(self.pending.popleft())
                self.log = self.log[-3:]
                self.delay = 14
            elif self.battle.outcome:
                self.trace("VICTORY START" if self.battle.outcome == "VICTORY" else "BATTLE END")
                stop_battle_music()
                self.notice_timer = 0
                self.set_result_pages(self.session.settle())
                self.trace("REWARD GROWTH MASTERY SPARK COMPLETE")
                self.result_page = 0
                self.state = "result"
                self.trace("RESULT")
                if self.battle.outcome == "VICTORY":
                    if play_victory_music():
                        self.fanfare_started_at = time.monotonic()
                        self.fanfare_start_frame = pyxel.frame_count
                        self.fanfare_timed_out = False
                        self.fanfare_visual_frames = 0
                        self.trace("FANFARE START")
                    else:
                        self.fanfare_started_at = None
                        self.trace("FANFARE UNAVAILABLE")
            elif self.battle.queue:
                visual = self.battle_visual()
                if visual.start():
                    action = self.battle.queue[0][1]
                    name = self.battle.skills[action.skill_id].name if action.kind == 'SKILL' else action.item_id
                    self.log = (self.log + [self.session.party[action.actor].name + ' ' + name])[-3:]
                else:
                    self.apply_visual_action()
            else:
                self.begin_input()
            return
        if self.state == "command":
            if self.pressed(pyxel.KEY_A):
                self.battle.begin_round(self.battle.auto_actions())
                self.state, self.delay = "resolve", 0
                self.log = [f"第{self.battle.round}ターン / 自動"]
                return
            vertical, horizontal = self.direction(), self.direction(horizontal=True)
            self.cursor = (((self.cursor // 2 + vertical) % 2) * 2
                           + (self.cursor % 2 + horizontal) % 2)
            if cancel and self.actions:
                self.actions.pop()
                self.actor_position -= 1
                self.cursor = 0
            elif confirm:
                if self.cursor == 0:
                    if self.actor.skills:
                        self.state, self.skill_cursor = "skill", self.actor.remembered_skill_index()
                    else:
                        self.tell("使える技がありません")
                elif self.cursor == 1:
                    self.state, self.item_cursor = "battle_item", 0
                elif self.cursor == 2:
                    self.commit(Action(self.actor_index, "GUARD"))
                else:
                    lines = self.battle.attempt_run()
                    if self.battle.boss:
                        self.tell(lines[0])
                    else:
                        self.actions.clear()
                        self.pending = deque(lines)
                        self.state, self.delay = "resolve", 0
                        if self.battle.outcome == 'ESCAPE':
                            self.log = lines
                            self.pending.clear()
                            stop_battle_music()
                            self.battle_visual().start_run()
                            play_cue('run_success')
        elif self.state == "battle_item":
            options = self.battle_items()
            if cancel:
                self.state = "command"
                self.selected_item = None
            elif options:
                self.item_cursor = (self.item_cursor + self.direction()) % len(options)
                if confirm:
                    self.selected_item = options[self.item_cursor]
                    if self.selected_item == AMRITA_ITEM_ID:
                        self.commit(Action(self.actor_index, 'ITEM', item_id=AMRITA_ITEM_ID))
                    elif not self.targets():
                        self.tell("使える対象がいません")
                    else:
                        self.state, self.target_cursor = "target", 0
            elif confirm:
                self.tell("使える道具がありません")
        elif self.state == "skill":
            if not self.actor.skills:
                self.state = "command"
                self.tell("使える技がありません")
                return
            self.skill_cursor = (self.skill_cursor + self.direction()) % len(self.actor.skills)
            if cancel:
                self.state = "command"
                self.selected_skill = None
            elif confirm:
                skill = self.session.skills[self.actor.skills[self.skill_cursor]]
                if self.actor.skill_uses.get(skill.id, 0) <= 0:
                    self.tell("残り回数がありません")
                elif skill.effect == "return":
                    self.tell("RETURNは探索メニューから使用")
                elif self.actor.cooldowns.get(skill.id, 0):
                    self.tell("この技は再使用待ちです")
                elif skill.target == "self":
                    self.commit(Action(self.actor_index, "SKILL", self.actor_index, skill.id))
                elif skill.target in AUTO_TARGETS:
                    self.commit(Action(self.actor_index, "SKILL", 0, skill.id))
                else:
                    self.selected_skill = skill
                    if not self.targets():
                        self.selected_skill = None
                        self.tell("使える対象がいません")
                    else:
                        self.state, self.target_cursor = "target", 0
        elif self.state == "target":
            choices = self.targets()
            if not choices:
                self.state = "battle_item" if self.selected_item else "skill"
                return
            self.target_cursor = (self.target_cursor + self.direction() + self.direction(horizontal=True)) % len(choices)
            if cancel:
                self.state = "battle_item" if self.selected_item else "skill"
                self.selected_item = None
                self.selected_skill = None
            elif confirm:
                target = choices[self.target_cursor][0]
                if self.selected_item:
                    self.commit(Action(self.actor_index, "ITEM", target, item_id=self.selected_item))
                else:
                    self.commit(Action(self.actor_index, "SKILL", target, self.selected_skill.id))

    def panel(self, x, y, w, h):
        pyxel.rect(x, y, w, h, 0)
        pyxel.rectb(x, y, w, h, 2)

    def footer(self, value):
        pyxel.rect(0, 111, 160, 9, 1)
        text(4, 112, self.notice if self.notice_timer else value, 3, 38)

    def title(self, value):
        pyxel.rect(0, 0, 160, 11, 3)
        text(4, 2, value, 0, 38)

    def draw(self):
        pyxel.cls(0)
        if self.overlay == 'rescue':
            if getattr(self, 'battle', None):
                self.draw_battle()
            self.draw_rescue_notice()
            return
        if self.overlay == 'status_debug':
            self.draw_status_debug()
        elif self.state == 'amrita_effect':
            try:
                pyxel.camera(*self.final_visual().shake_offset())
                self.draw_battle()
                self.final_visual().draw_light(pyxel)
            except Exception as error:
                # A presentation fault must never hold a resolved ITEM action.
                self.trace('AMRITA VISUAL UNAVAILABLE: ' + type(error).__name__)
                self.finish_amrita_effect()
            finally:
                pyxel.pal()
                pyxel.camera()
        elif self.overlay == "debug_skills":
            self.draw_debug_skills()
        elif self.overlay == "help":
            self.draw_help()
        elif self.overlay == "info":
            self.draw_info()
        elif self.state == "result":
            self.draw_result()
        elif self.state == "replace":
            self.draw_replacement()
        elif self.state == "skill":
            self.draw_skills()
        elif self.state == "battle_item":
            self.draw_battle_items()
        else:
            shake = self.battle_visual().shake_offset()
            if shake != (0, 0):
                pyxel.camera(*shake)
            elif self.shake_timer:
                offsets = ((-2, 0), (2, 1), (-1, -1), (1, 0), (0, 1), (0, 0))
                pyxel.camera(*offsets[6 - self.shake_timer])
            self.draw_battle()
            if self.shake_timer or shake != (0, 0):
                pyxel.camera()

    def draw_battle(self):
        flag = " DEBUG" if self.session.debug else ""
        self.title(f"第{self.session.completed + 1}戦 {self.battle.round + (self.state not in ('resolve', 'amrita_effect'))}ターン{flag}")
        visual = self.battle_visual()
        area = None if self.battle.is_elysion_battle else getattr(self, 'battle_background_area', None)
        if area is None:
            pyxel.rect(0, 67, 96, 13, 0)
            for x in range(5, 91, 8):
                pyxel.pset(x, 75, 1)
        else:
            draw_battle_background(pyxel, area)
        for i, enemy in enumerate(self.battle.enemies):
            x, y = enemy_position(i, len(self.battle.enemies))
            x += visual.enemy_offset(i)
            visible, sink = visual.enemy_visual(i)
            if visible:
                if self.battle.is_elysion_battle and enemy.id == LORD_OF_ELYSION_ID:
                    flashing = visual.target_flashing('enemy', i)
                    if flashing:
                        pyxel.pal(1, 3); pyxel.pal(2, 3)
                    self.draw_lord_of_elysion(enemy)
                    if flashing:
                        pyxel.pal()
                else:
                    pyxel.clip(0, 11, 96, y + 16 - 11)
                    flashing = visual.target_flashing('enemy', i)
                    if flashing:
                        pyxel.pal(1, 3); pyxel.pal(2, 3)
                    pyxel.blt(x, y + sink, 0, *enemy.sprite, 16, 16, 0)
                    if flashing:
                        pyxel.pal()
                    pyxel.clip()
                if enemy.alive:
                    icon_x, icon_y = x - 9, y
                    if self.battle.is_elysion_battle:
                        fx, fy, _, _ = self.final_visual().bounds()
                        icon_x, icon_y = fx - 9, fy
                    draw_status_icons(pyxel, enemy, max(0, icon_x), icon_y, limit=2,
                                      vertical=True, definitions=self.battle.status_definitions)
        for i, actor in enumerate(self.session.party):
            y = 13 + i * 16
            active = (self.state in ("command", "target", "battle_transition") and self.actor_index == i
                      or visual.active and visual.actor == i)
            pyxel.rect(97, y, 62, 16, 1 if active else 0)
            offset = visual.actor_offset(i)
            running = visual.phase == 'run_success'
            recoiling = visual.party_recoiling(i)
            showing_hit = visual.holds_party_sprite(i)
            if actor.alive or showing_hit:
                flashing = visual.target_flashing('party', i)
                if flashing:
                    pyxel.pal(1, 3); pyxel.pal(2, 3)
                pyxel.blt(98 + offset, y, 0, *actor.sprite, -16 if running else 16, 16, 0)
                if flashing:
                    pyxel.pal()
                if not running and actor.alive:
                    draw_status_icons(pyxel, actor, 82 + offset,
                                      y + 3, limit=2,
                                      definitions=self.battle.status_definitions)
            else:
                pyxel.blt(98 + offset, y, ASSET_BANK, KO_SPRITE_U, KO_SPRITE_V,
                          -KO_SPRITE_W if running else KO_SPRITE_W, KO_SPRITE_H, 0)
            if running:
                continue  # Leave room for the four moving sprites, without text overlap.
            label_x = 119 if recoiling else 115
            shown_hp = visual.displayed_hp(i)
            text(label_x, y + 1, actor.name, 3 if shown_hp > 0 else 1, 6 if recoiling else 7)
            status = "KO" if shown_hp <= 0 else "!" if actor.berserk else "+" if actor.guarding else ""
            text(148, y + 1, status, 3, 2)
            text(label_x, y + 8, f"{shown_hp}/{actor.max_hp}", 2, 11)
        visual.draw_effect(pyxel)
        self.panel(1, 80, 158, 31)
        if self.state in ("command", "battle_transition"):
            for i, label in enumerate(("SKILL 技", "ITEM 道具", "GUARD まもる", "RUN 逃走")):
                text(5 + i % 2 * 75, 84 + i // 2 * 12,
                     (">" if i == self.cursor else " ") + label,
                     3 if i == self.cursor else 2)
            self.footer("A:決定 B:戻る D-PAD:選択")
        elif self.state == "target":
            target_index, target = self.targets()[self.target_cursor]
            ally = self.selected_item or (self.selected_skill and self.selected_skill.target == "ally")
            if ally:
                pyxel.rectb(97, 13 + target_index * 16, 62, 16, 3)
            else:
                if self.battle.is_elysion_battle:
                    x, y, _, h = self.final_visual().bounds()
                    text(x - 8, y + h // 2 - 4, ">", 3)
                else:
                    x, y = enemy_position(target_index, len(self.battle.enemies))
                    text(x - 8, y + 4, ">", 3)
            label = self.selected_item or f"{self.selected_skill.name} 残{self.actor.skill_uses[self.selected_skill.id]}"
            text(5, 84, label, 2, 37)
            target_line = f"> {target.name} HP {target.hp}/{target.max_hp}" if ally else f"> {target.name}"
            text(5, 92, target_line, 3, 37)
            hint = self.cure_target_hint(self.selected_skill, [target]) if not self.selected_item else ""
            text(5, 100, hint + " / 予約可" if hint else "対象を選んでください", 2, 37)
            self.footer("D-PAD:対象 A:決定 B:戻る")
        else:
            for i, line in enumerate(self.log[-3:]):
                text(5, 84 + i * 8, line, 3 if i == len(self.log[-3:]) - 1 else 2, 37)
            self.footer("" if self.state == 'amrita_effect' else "A:メッセージ送り / 長押しで高速")
        visual.legend.draw_name(pyxel, visual.phase)

    def battle_visual(self):
        visual = getattr(self, 'battle_presentation', None)
        if visual is None or visual.battle is not self.battle:
            self.battle_presentation = visual = BattlePresentation(self.battle)
        return visual

    def apply_visual_action(self):
        visual = self.battle_visual()
        before = [enemy.alive for enemy in self.battle.enemies]
        hp_before = [actor.hp for actor in self.session.party]
        barrier_before = self.battle.elysion_barrier_active
        self.pending.extend(wrap_lines(self.battle.step()))
        play_cue(self.battle.sound_cue)
        visual.after_action(before, hp_before)
        if self.battle.player_hit:
            # Strong hits shake at visual impact, for three frames, not during wind-up.
            self.shake_timer = 0 if visual.enemy_action == 'heavy_attack' else 6
        if visual.phase == 'enemy_death':
            play_cue('enemy_defeat')  # Once per death group, never once per blink.
        if barrier_before and not self.battle.elysion_barrier_active:
            visual.reset()
            self.start_amrita_effect()

    def update_battle_visual(self):
        self.shake_timer = max(0, self.shake_timer - 1)
        previous_phase = self.battle_visual().phase
        event = self.battle_visual().advance()
        if previous_phase != 'enemy_death' and self.battle_visual().phase == 'enemy_death':
            play_cue('enemy_defeat')
        if event == 'apply':
            self.apply_visual_action()
        elif event == 'escaped':
            self.session.settle()
            self.pending.clear()
            self.finish_results()

    def set_result_pages(self, lines):
        self.growth_result_pages = result_pages(lines, self.session.party)
        # Retain the existing 9-lines-per-page interface used by result controls.
        self.result_lines = [line for page in self.growth_result_pages
                             for line in page['lines'] + [''] * (9 - len(page['lines']))]

    def final_visual(self):
        if getattr(self, 'final_presentation', None) is None:
            self.final_presentation = FinalPresentation(getattr(self, 'final_battle_data', None))
        return self.final_presentation

    def draw_lord_of_elysion(self, enemy):
        self.final_visual().draw_boss(pyxel, enemy, self.battle.elysion_barrier_active)

    def start_amrita_effect(self):
        # The model has already applied the legal ITEM action and released the barrier.
        # Only presentation pauses here, never sound or the game rule itself.
        self.overlay, self.notice_timer, self.shake_timer = None, 0, 0
        self.pending.clear()
        self.log = wrap_lines(self.battle.final_data['amrita_release'][:1], 37)[-3:]
        try:
            self.final_visual().start()
            self.state = 'amrita_effect'
        except Exception:
            self.finish_amrita_effect()

    def finish_amrita_effect(self):
        if getattr(self, 'final_presentation', None) is not None:
            self.final_presentation.reset()
        self.log = wrap_lines(self.battle.final_data['amrita_release'][1:] or
                              self.battle.final_data['amrita_release'], 37)[-3:]
        self.state, self.delay = 'resolve', 14
        # DungeonApp consumes a released frame before accepting subsequent input.
        self.battle_input_blocked = True

    def update_amrita_effect(self):
        if self.pressed(pyxel.KEY_Q):
            pyxel.quit()
            return
        try:
            visual = self.final_visual()
            finished = visual.advance()
        except Exception:
            self.finish_amrita_effect()
            return
        if finished:
            self.finish_amrita_effect()
        elif visual.frame >= AMRITA_MESSAGE_FRAME:
            self.log = wrap_lines(self.battle.final_data['amrita_release'][1:] or
                                  self.battle.final_data['amrita_release'], 37)[-3:]

    def cure_target_hint(self, skill, targets):
        """Advisory only: healthy allies remain legal queued cure targets."""
        if skill and skill.effect == 'cure' and not any(
                target.alive and set(active_statuses(target)) & set(skill.cure_statuses)
                for target in targets):
            return "治療対象なし"
        return ""

    def skill_details(self, actor, skill, y=76):
        pyxel.line(4, y - 3, 155, y - 3, 1)
        text(5, y, f"{RARITIES[skill.rarity]} / {TARGETS[skill.target]} 最大{actor.max_uses(skill)}回", 2, 37)
        text(5, y + 8, skill.formula(), 3, 37)
        detail = f"威力 {skill.power(actor)} 待ち {skill.cooldown}T"
        if actor.power_multiplier(skill) > 1:
            detail += " / MASTER x1.2"
        if skill.effect == "berserk":
            detail = "STR x1.5 / 被害 x1.25 / 3T"
        elif skill.effect in EFFECTS:
            detail = EFFECTS[skill.effect] + " / 重複せず更新"
        elif skill.effect == "return":
            detail = f"未確定{CURRENCY_NAME}を持ち帰る"
        elif skill.effect == "revive":
            detail = "戦闘不能の味方1人 / 残数制"
        if skill.target == 'all_allies':
            hint = self.cure_target_hint(skill, self.session.party)
            if hint:
                detail = hint + (" / 予約可" if self.state == 'skill' else "")
        text(5, y + 16, detail, 2, 37)
        text(5, y + 24, skill.description, 2, 37)

    def draw_skills(self):
        if not self.actor.skills:
            self.title(f"{self.actor.name} / 技なし")
            self.footer("B:戻る")
            return
        self.skill_cursor = min(max(0, self.skill_cursor), len(self.actor.skills) - 1)
        self.title(f"{self.actor.name} / 技 {self.skill_cursor + 1}/{len(self.actor.skills)}")
        start = max(0, self.skill_cursor - 5)
        for row, skill_id in enumerate(self.actor.skills[start:start + 6]):
            skill = self.session.skills[skill_id]
            selected = start + row == self.skill_cursor
            y = 16 + row * 9
            if selected:
                pyxel.rect(3, y - 1, 154, 8, 1)
            text(5, y, (">" if selected else " ") + skill.name, 3, 23)
            wait = self.actor.cooldowns.get(skill_id, 0)
            text(101, y, f"{self.actor.skill_uses.get(skill_id, 0)}/{self.actor.max_uses(skill)}" + ("待" if wait else ""), 2, 14)
        self.skill_details(self.actor, self.session.skills[self.actor.skills[self.skill_cursor]])
        self.footer("D-PAD:選択 A:使用 B:戻る")

    def draw_battle_items(self):
        self.title(f"{self.actor.name} / ITEM")
