"""Exploration state. Every terrain/event position comes from Tilemap.pget()."""
from collections import Counter, deque
import json
import math

from .content import ROOT
from .models import Enemy
from .labels import CURRENCY_NAME
from .treasure import Treasure
from .exploration import load_exploration_settings
from .items import Inventory
from .finale import FinaleProgress
from .elevator import unlock_notice
from .tiles import (BOSS_FLOORS, MAP_IMAGE_BANK, PASSABLE, FLOOR_TILES, TILE_FLOOR,
                    TILE_STAIRS_UP, TILE_STAIRS_DOWN, TILE_CHEST, TILE_ENTRANCE,
                    TILE_CHEST_OPEN, TILE_BOSS, TILE_BOSS_CLEAR,
                    TILE_RARE_CHEST, TILE_POISON, TILE_PIT, PIT_TILES, TILE_HEAL_POINT,
                    TILE_QUEST, TILE_SWITCH, TILE_SWITCH_ON, TILE_DOOR, TILE_DOOR_OPEN,
                    LORE_TILES, TILE_GUARDIAN, TILE_WARNING)


def load_dungeon_settings():
    return json.loads((ROOT / "data" / "dungeon.json").read_text(encoding="utf-8-sig"))


class Dungeon:
    def __init__(self, tilemaps, enemy_data, settings, rng, treasure=None, inventory=None):
        self.maps = list(tilemaps)
        self.settings, self.rng = settings, rng
        self.exploration_settings = load_exploration_settings()
        self.last_reward = None
        self.enemies = {row["id"]: row for row in enemy_data}
        if len(self.enemies) != len(enemy_data):
            raise ValueError("enemies.json: 敵のidが重複しています。")
        self.width, self.height = settings["width"], settings["height"]
        self.finale = FinaleProgress()
        self.validate_settings()
        self.validate_maps()
        self.floor = 0
        self.x, self.y = self.find(0, TILE_ENTRANCE)
        self.opened = set()
        self.activated_switches = set()  # Floor IDs, retained until the next expedition.
        self.chest_loot = {}
        self.inventory = inventory if inventory is not None else Inventory()
        self.treasure = treasure if treasure is not None else Treasure()
        self.steps = 0
        self.grace = 0  # Legacy checkpoint field only; never an encounter gate.
        # Construction/load must not consume RNG. An expedition draws in enter().
        self.encounter_remaining = settings['encounter_step_ranges'][0][0]
        self.defeated_bosses = set()

    @property
    def cleared(self):
        return BOSS_FLOORS[-1] in self.defeated_bosses

    @property
    def potions(self):
        return self.inventory.counts["POTION"]

    @potions.setter
    def potions(self, value):
        self.inventory.counts["POTION"] = value

    @property
    def spark_multiplier(self):
        return self.settings["spark_multipliers"][self.floor]

    @property
    def boss_data(self):
        return self.enemies[self.settings["floors"][self.floor]["boss_id"]]

    def defeat_boss(self):
        if self.floor not in BOSS_FLOORS:
            raise ValueError("この階にボスはいません。")
        first = self.floor not in self.defeated_bosses
        if self.floor == 14:
            self.finale.claim_amrita()
            self.defeated_bosses.add(self.floor)
            lines = self.finale.data['demon_after']
        else:
            self.defeated_bosses.add(self.floor)
            lines = self.boss_data["after_message"]
        # Append only to the first victory's existing, safely paginated story.
        return list(lines) + (unlock_notice(self.floor) if first else [])

    def validate_settings(self):
        def require(ok, message):
            if not ok:
                raise ValueError("dungeon.json: " + message)
        def number(v, lo, hi):
            return type(v) in (int, float) and math.isfinite(v) and lo <= v <= hi
        max_width = min(tilemap.width for tilemap in self.maps)
        max_height = min(tilemap.height for tilemap in self.maps)
        require(type(self.width) is int and 8 <= self.width <= max_width,
                f"widthは8～{max_width}")
        require(type(self.height) is int and 8 <= self.height <= max_height,
                f"heightは8～{max_height}")
        ranges = self.settings.get('encounter_step_ranges')
        require(isinstance(ranges, list) and len(ranges) == 3 and all(
                isinstance(r, list) and len(r) == 2 and all(type(v) is int for v in r)
                and 1 <= r[0] <= r[1] <= 999 for r in ranges),
                'encounter_step_rangesはAREA1～3の整数[min,max] (1～999)')
        items = self.settings["items"]
        require(type(items["max_potions"]) is int and 1 <= items["max_potions"] <= 99, "max_potionsは1～99")
        require(type(items["initial_potions"]) is int and 0 <= items["initial_potions"] <= items["max_potions"], "初期ポーション数が無効")
        require(type(items["potion_heal"]) is int and 1 <= items["potion_heal"] <= 9999, "potion_healは1～9999")
        require(len(self.maps) == len(self.settings["floors"]) == 15, "マップとfloorsは15階分必要")
        multipliers = self.settings["spark_multipliers"]
        require(len(multipliers) == 15 and all(number(v, 0.01, 100) for v in multipliers), "spark_multipliersは15階分の正の倍率")
        require(multipliers == sorted(multipliers), "spark_multipliersは浅い順に同値か増加")
        for floor, row in enumerate(self.settings["floors"]):
            width, height = self.map_bounds(floor)
            points = row.get('quest_spawn_points', [])
            require(isinstance(points, list) and all(
                isinstance(p, list) and len(p) == 2 and all(type(v) is int for v in p)
                for p in points), f'{floor + 1}F: quest_spawn_pointsは整数座標2個の配列です')
            require(type(width) is int and 8 <= width <= self.maps[floor].width,
                    f'{floor + 1}F: widthはTilemap内の8以上の整数です')
            require(type(height) is int and 8 <= height <= self.maps[floor].height,
                    f'{floor + 1}F: heightはTilemap内の8以上の整数です')
            if floor in BOSS_FLOORS:
                boss = self.enemies.get(row.get("boss_id"), {})
                require(boss.get("boss") and boss.get("floor") == floor + 1, "ボスIDまたは出現floorが無効")
                for key in ("message", "after_message"):
                    lines = boss.get(key)
                    require(isinstance(lines, list) and bool(lines) and all(isinstance(s, str) and s.strip() for s in lines), "ボスの" + key + "は空でない文章の配列")
                continue
            require(len(row["enemy_ids"]) == len(row["weights"]) > 0, "敵候補と重みの数が不一致")
            require(all(i in self.enemies and not self.enemies[i].get("boss") for i in row["enemy_ids"]), "通常敵IDが無効")
            require(all(number(w, 0.001, 10000) for w in row["weights"]), "敵の重みは正の数")
            require(len(row["count"]) == 2 and all(type(v) is int for v in row["count"]) and 1 <= row["count"][0] <= row["count"][1] <= 4, "敵数は1～4")
            require(all(number(row[k], 0.1, 20) for k in ("hp_scale", "power_scale")), "敵の倍率が無効")
        for ident in self.finale.data['guardian_ids']:
            row = self.enemies.get(ident, {})
            require(row.get('boss') and row.get('floor') == 15, '守護者はfloor 15のboss敵が必要です')

    def map_bounds(self, floor):
        profile = self.settings['floors'][floor]
        return profile.get('width', self.width), profile.get('height', self.height)

    def tile(self, floor, x, y):
        width, height = self.map_bounds(floor)
        if not (0 <= x < width and 0 <= y < height):
            return None
        return tuple(self.maps[floor].pget(x, y))

    def positions(self, floor, tile):
        width, height = self.map_bounds(floor)
        return [(x, y) for y in range(height) for x in range(width)
                if self.tile(floor, x, y) == tile]

    def floor_appearance(self, floor, x, y):
        """Use a nearby authored floor when covering an event marker."""
        width, height = self.map_bounds(floor)
        for radius in range(1, max(width, height)):
            candidates = [self.tile(floor, px, py)
                          for py in range(max(0, y - radius), min(height, y + radius + 1))
                          for px in range(max(0, x - radius), min(width, x + radius + 1))
                          if max(abs(px - x), abs(py - y)) == radius
                          and self.tile(floor, px, py) in FLOOR_TILES]
            if candidates:
                return Counter(candidates).most_common(1)[0][0]
        return TILE_FLOOR

    def find(self, floor, tile):
        positions = self.positions(floor, tile)
        if len(positions) != 1:
            raise ValueError(f"{floor + 1}F: タイル{tile}を1個配置してください。")
        return positions[0]

    def validate_maps(self):
        self.boss_positions = {}
        for floor, tilemap in enumerate(self.maps):
            width, height = self.map_bounds(floor)
            if tilemap.imgsrc != MAP_IMAGE_BANK:
                raise ValueError(f"{floor + 1}FのImage Bankは1にしてください。")
            start = self.find(floor, TILE_ENTRANCE if floor == 0 else TILE_STAIRS_UP)
            if floor < len(self.maps) - 1:
                self.find(floor, TILE_STAIRS_DOWN)
            if floor in BOSS_FLOORS:
                self.boss_positions[floor] = self.find(floor, TILE_BOSS)
            if self.positions(floor, TILE_ENTRANCE) and floor != 0:
                raise ValueError("入口は1Fに配置してください。")
            if (floor == 0 and self.positions(floor, TILE_STAIRS_UP)) or (floor == 14 and self.positions(floor, TILE_STAIRS_DOWN)):
                raise ValueError("B1Fの上り階段・B15Fの下り階段は不要です。")
            if floor not in BOSS_FLOORS and self.positions(floor, TILE_BOSS):
                raise ValueError("ボスはB5F/B10F/B15Fに配置してください。")
            if self.positions(floor, TILE_DOOR) and not self.positions(floor, TILE_SWITCH):
                raise ValueError(f"{floor + 1}F: 閉扉には同じ階のスイッチが必要です。")
            if floor == 14:
                self.find(floor, TILE_GUARDIAN)
                self.find(floor, TILE_WARNING)
                self.find(floor, TILE_HEAL_POINT)
            elif self.positions(floor, TILE_GUARDIAN) or self.positions(floor, TILE_WARNING):
                raise ValueError('守護者・警告地点はB15Fだけに配置してください。')
            for y in range(height):
                for x in range(width):
                    tile = self.tile(floor, x, y)
                    if tile in LORE_TILES and self.finale.lore_at(floor, tile) is None:
                        raise ValueError(f'{floor + 1}F: この石碑タイルには文章がありません。')
            seen = self._reachable(floor, through_stairs=True)
            events = {TILE_CHEST, TILE_RARE_CHEST, TILE_HEAL_POINT, TILE_STAIRS_UP, TILE_STAIRS_DOWN, TILE_ENTRANCE, TILE_BOSS, TILE_QUEST, TILE_SWITCH, TILE_DOOR, TILE_GUARDIAN, TILE_WARNING} | LORE_TILES
            for y in range(height):
                for x in range(width):
                    if self.tile(floor, x, y) in events and (x, y) not in seen:
                        raise ValueError(f"{floor + 1}F ({x},{y}) のイベントへ通路がつながっていません。")

    def reachable(self, floor):
        """Potential quest reachability, including doors unlocked by a reachable switch."""
        return self._reachable(floor)

    def _reachable(self, floor, through_stairs=False):
        start = self.find(floor, TILE_ENTRANCE if floor == 0 else TILE_STAIRS_UP)
        allowed = PASSABLE - PIT_TILES
        if not through_stairs:
            allowed -= {TILE_ENTRANCE, TILE_STAIRS_UP, TILE_STAIRS_DOWN}
        for doors_open in (False, True):
            seen, queue = {start}, deque([start])
            while queue:
                x, y = queue.popleft()
                for dx, dy in ((0, -1), (0, 1), (-1, 0), (1, 0)):
                    point = x + dx, y + dy
                    tile = self.tile(floor, *point)
                    if point not in seen and (tile in allowed or doors_open and tile == TILE_DOOR):
                        seen.add(point)
                        queue.append(point)
            if doors_open or not any(self.tile(floor, *p) == TILE_SWITCH for p in seen):
                return seen

    def can_enter(self, floor, x, y):
        tile = self.tile(floor, x, y)
        if tile == TILE_GUARDIAN:
            return self.finale.guardians_defeated
        return tile in PASSABLE or tile == TILE_DOOR and floor in self.activated_switches

    def grant_chest(self, reward):
        """Apply inventory rewards; the field UI applies HP/spark effects once."""
        kind, amount = reward["kind"], reward.get("amount", 1)
        if kind in ("POTION", "PHOENIX ASH", "REMEDY") and self.inventory.counts[kind] + amount > 9:
            return "", f"{kind} は満杯。宝箱は残した"
        self.last_reward = reward
        if kind == "TREASURE":
            self.treasure.unbanked += amount
            message = f"{amount} {CURRENCY_NAME}を手に入れた。未確定 / 帰還で確定"
        elif kind in ("POTION", "PHOENIX ASH", "REMEDY"):
            self.inventory.add(kind, amount)
            message = f"{kind} を{amount}個入手"
        else:
            message = "宝箱は空だった" if kind == "EMPTY" else "宝箱を開けた!"
        return "chest", message

    def fall_in_pit(self):
        self.x, self.y = self.find(self.floor, TILE_ENTRANCE if self.floor == 0 else TILE_STAIRS_UP)
        # The triggering tile was one real step; the teleport grants no steps.
        return "pit", "落とし穴! この階の入口へ戻された"

    def reset_encounter(self, floor=None):
        """Draw once per new expedition/battle exit, including both endpoints."""
        area = (self.floor if floor is None else floor) // 5
        self.encounter_remaining = self.rng.randint(*self.settings['encounter_step_ranges'][area])

    def enter(self, allow_cleared=False, *, encounter_floor=0):
        if self.cleared and not allow_cleared:
            raise ValueError("このダンジョンはクリア済みです。")
        self.floor = 0
        self.x, self.y = self.find(0, TILE_ENTRANCE)
        self.opened.clear()
        self.activated_switches.clear()
        self.chest_loot.clear()
        self.finale.abort_guardians()
        self.grace = 0
        self.reset_encounter(encounter_floor)

    def change_floor(self, floor):
        if not 0 <= floor < len(self.maps):
            return "", "これ以上進めません"
        if floor > self.floor:
            for gate in BOSS_FLOORS[:-1]:
                if floor > gate and gate not in self.defeated_bosses:
                    return "", f"B{gate + 1}Fのボスを倒す必要がある"
        arrival = TILE_STAIRS_UP if floor > self.floor else TILE_STAIRS_DOWN
        point = self.find(floor, arrival)  # Resolve before changing state.
        self.floor = floor
        self.x, self.y = point
        # Carry the remaining budget. Stair/confirmation loops cannot refill it.
        return "stairs", f"B{floor + 1}Fに到着"

    def debug_floor(self, floor):
        self.floor = max(0, min(len(self.maps) - 1, floor))
        self.x, self.y = self.find(self.floor, TILE_ENTRANCE if self.floor == 0 else TILE_STAIRS_UP)
        self.reset_encounter()

    def interact(self):
        tile = self.tile(self.floor, self.x, self.y)
        if tile in LORE_TILES:
            return 'lore', self.finale.lore_at(self.floor, tile)
        if tile in (TILE_GUARDIAN, TILE_WARNING):
            if not self.finale.guardians_defeated:
                return 'guardian', self.finale.data['guardian_warning'][0]
            return '', '守護者の気配は消えている'
        if tile == TILE_SWITCH:
            if self.floor in self.activated_switches:
                return "", "スイッチはON。扉は開いている"
            self.activated_switches.add(self.floor)
            return "switch", "スイッチON! この階の扉が開いた"
        if tile == TILE_ENTRANCE:
            return "base", "入口から帰還した"
        if tile == TILE_STAIRS_UP:
            return self.change_floor(self.floor - 1)
        if tile == TILE_STAIRS_DOWN:
            return self.change_floor(self.floor + 1)
        if tile == TILE_BOSS:
            if self.floor == 14 and not self.finale.guardians_defeated:
                return 'guardian', self.finale.data['guardian_warning'][0]
            if self.floor not in self.defeated_bosses:
                return "boss", self.boss_data["name"]
            return "", "この階のボスは撃破済み"
        if tile == TILE_HEAL_POINT:
            return "spring", "回復の泉"
        if tile in (TILE_CHEST, TILE_RARE_CHEST):
            key = self.floor, self.x, self.y
            if key in self.opened:
                return "", "宝箱は空です"
            if key not in self.chest_loot:
                rows = self.exploration_settings["CHEST_REWARD_TABLE"]["RARE" if tile == TILE_RARE_CHEST else "NORMAL"]
                self.chest_loot[key] = self.rng.choices(rows, [r["weight"] for r in rows])[0].copy()
            result = self.grant_chest(self.chest_loot[key])
            if result[0]:
                self.opened.add(key)
            return result
        return "", "特に何もありません"

    def move(self, dx, dy, debug=False):
        if abs(dx) + abs(dy) != 1:
            return "", ""
        x, y = self.x + dx, self.y + dy
        if not self.can_enter(self.floor, x, y):
            if self.tile(self.floor, x, y) == TILE_GUARDIAN:
                return 'guardian', self.finale.data['guardian_warning'][0]
            if self.tile(self.floor, x, y) == TILE_DOOR:
                return "", "閉じた扉。同じ階のスイッチを探そう"
            return "", "壁で進めません"
        self.x, self.y = x, y
        self.steps += 1
        # Only completed grid moves count. Event tiles own their move; a due
        # encounter stays at zero until an eligible cell or an event battle exit.
        self.encounter_remaining = max(0, self.encounter_remaining - 1)
        tile = self.tile(self.floor, x, y)
        if tile == TILE_POISON:
            return "poison", "毒沼に足を踏み入れた"
        if tile in PIT_TILES:
            return self.fall_in_pit()
        if tile == TILE_SWITCH:
            return "", "スイッチ: Aで操作" if self.floor not in self.activated_switches else "スイッチはON"
        if tile in LORE_TILES:
            return '', '石碑: Aで読む'
        if tile not in FLOOR_TILES and tile not in (TILE_CHEST_OPEN, TILE_BOSS_CLEAR, TILE_QUEST,
                        TILE_DOOR, TILE_DOOR_OPEN, TILE_SWITCH_ON, TILE_GUARDIAN):
            return self.interact()
        # Only B15 is a dedicated finale floor without random encounters.
        # B5/B10 still encounter while exploring, before and after their bosses.
        if self.floor == 14:
            return "", ""
        if self.encounter_remaining == 0:
            return "battle", "敵と遭遇した!"
        return "", ""

    def make_enemies(self, boss=False, guardian_index=None):
        profile = self.settings["floors"][self.floor]
        if guardian_index is not None:
            if self.floor != 14 or guardian_index not in (0, 1, 2):
                raise ValueError('守護者はB15Fの3体です。')
            rows = [self.enemies[self.finale.data['guardian_ids'][guardian_index]]]
            boss = True
            hp_scale = power_scale = 1
        elif boss:
            rows = [self.boss_data]
            hp_scale = power_scale = 1
        else:
            # Boss-only profiles reuse the preceding area's ordinary enemies,
            # just as hunt quests do; keep their existing weights and stats.
            if "enemy_ids" not in profile:
                profile = self.settings["floors"][self.floor - 1]
            ids = self.rng.choices(profile["enemy_ids"], profile["weights"], k=self.rng.randint(*profile["count"]))
            rows = [self.enemies[i] for i in ids]
            hp_scale, power_scale = profile["hp_scale"], profile["power_scale"]
        return [Enemy.from_definition(row,
                      name=row["name"] + ("" if boss else f" {chr(65 + i)}"),
                      max_hp=max(1, round(row["max_hp"] * hp_scale)),
                      strength=max(1, round(row["str"] * power_scale)),
                      intellect=max(1, round(row["int"] * power_scale)))
                for i, row in enumerate(rows)]

    def use_potion(self, character):
        return self.inventory.use("POTION", character)[1]

sources.rpg/exploration.py:
"""Field rewards and one JSON-compatible quest, shared by all three types."""
import json
from random import Random
from .content import ROOT
from .growth import spark
from .quests import (QUEST_TYPES, QUEST_NAMES, QUEST_COMPLETION_IDS,
                     QUEST_COMPLETION_TOTAL, load_quest_settings,
                     load_quest_flavors, spawn_candidates, log_spawn_failure)
from .labels import CURRENCY_NAME
from .models import Enemy


def load_exploration_settings():
    data = json.loads((ROOT / "data/exploration.json").read_text(encoding="utf-8-sig"))
    kinds = {"TREASURE", "POTION", "PHOENIX ASH", "REMEDY", "SKILL_CHANCE", "TRAP", "EMPTY"}
    for rows in data["CHEST_REWARD_TABLE"].values():
        if not rows or sum(r["weight"] for r in rows) <= 0:
            raise ValueError("宝箱の重み合計は正の数が必要です")
        for row in rows:
            if row["kind"] not in kinds or row["weight"] < 0 or row.get("amount", 1) < 0 or not 0 <= row.get("chance", 1) <= 1:
                raise ValueError("宝箱テーブルの値が不正です")
    if data["poison_damage"] < 0:
        raise ValueError("探索ダメージは0以上です")
    return data


class Exploration:
    def __init__(self, session, dungeon):
        self.session, self.dungeon = session, dungeon
        self.quest_data = load_quest_settings()
        self.flavor_data = load_quest_flavors()
        # Flavor choices must not change target placement, combat or growth RNG.
        self.flavor_rng = Random()
        self.flavor_rng.setstate(session.rng.getstate())
        self.last_flavor_id = None
        self.active_quest = None
        self.pending_quest = None
        self.pending_quest_rng_state = None
        self.completed = set()
        self.quest_clear_counts = dict.fromkeys(QUEST_TYPES, 0)
        self.completed_quest_ids = []
        self.completion_ready = False
        self.springs = set()

    def unlocked(self, quest):
        return quest["gate"] is None or quest["gate"] - 1 in self.dungeon.defeated_bosses

    # Existing checkpoint/debug names are aliases; progress is stored only once.
    @property
    def active(self):
        return self.active_quest

    @active.setter
    def active(self, value):
        self.active_quest = value

    @property
    def target(self):
        q = self.active_quest
        return (q['target_floor'] - 1, *q['points'][0]) if q else None

    @target.setter
    def target(self, value):
        if self.active_quest and value is not None:
            self.active_quest['target_floor'] = value[0] + 1
            self.active_quest['points'][0] = list(value[1:])

    @property
    def surveyed(self):
        return bool(self.active_quest and self.active_quest['completed'])

    @surveyed.setter
    def surveyed(self, value):
        # Checkpoint restore writes the legacy False after restoring the full
        # quest dict. Preserve partial investigation progress on that no-op.
        if self.active_quest and bool(value) != self.surveyed:
            q = self.active_quest
            q['completed'] = bool(value)
            q['progress'] = q['required_count'] if value else 0
            q['investigated_points'] = [list(p) for p in q['points']] if value else []

    def reset_progress(self):
        self.completion_ready = False
        if self.active_quest:
            self.active_quest.update(completed=False, progress=0, investigated_points=[])

    def quest_name(self, quest=None):
        q = self.active_quest if quest is None else quest
        return f"{QUEST_NAMES[q['type']]} Lv{q['level']}" if q else ''

    def message(self, key):
        q = self.active_quest or {}
        values = dict(q, name=self.quest_name(), floor=q.get('target_floor'), currency=CURRENCY_NAME)
        return self.quest_data['messages'][key].format(**values)

    def available(self):
        return [(kind, row['level']) for kind in QUEST_TYPES
                for row in self.quest_data['levels'] if self.unlocked(row)]

    def choose_flavor(self, kind, level):
        pool = self.flavor_data['texts'].get(kind, {}).get(str(level), [])
        unseen = [row for row in pool if row['id'] in QUEST_COMPLETION_IDS[kind]
                  and row['id'] not in self.completed_quest_ids]
        candidates = unseen or pool
        choices = [row for row in candidates if row['id'] != self.last_flavor_id] or candidates
        row = (self.flavor_rng.choice(choices) if choices else
               self.flavor_data['fallbacks'][kind][str(level)])
        return row['id']

    def quest_flavor(self, quest=None):
        """Resolve only within this type/Lv; old or removed IDs use editable defaults."""
        q = self.active_quest if quest is None else quest
        if q is None:
            return None
        pool = self.flavor_data['texts'].get(q['type'], {}).get(str(q['level']), [])
        return next((row for row in pool if row['id'] == q.get('flavor_id')),
                    self.flavor_data['fallbacks'][q['type']][str(q['level'])])

    def make_quest(self, quest_id, debug=False, quest_type='explore', rng=None):
        """Generate a contract without activating it or recording acceptance."""
        if self.active_quest:
            raise ValueError(self.message('already_active'))
        if quest_type not in QUEST_TYPES or quest_id not in (1, 2, 3):
            raise ValueError('依頼の種別・Lvが不正です。')
        quest = next(q for q in self.quest_data['levels'] if q['level'] == quest_id)
        if not self.unlocked(quest) and not debug:
            raise ValueError("先のエリアのボス撃破が必要です")
        count = self.quest_data['investigate_points'][str(quest_id)] if quest_type == 'investigate' else 1
        candidates = {floor: spawn_candidates(self.dungeon, floor)
                      for floor in range(quest['floors'][0] - 1, quest['floors'][1])}
        for floor, points in candidates.items():
            if len(points) < count:
                log_spawn_failure(quest_type, quest_id, floor, count, len(points))
        candidates = {floor: points for floor, points in candidates.items() if len(points) >= count}
        if not candidates:
            raise ValueError('安全なQUEST候補地点が足りません。')
        rng = self.session.rng if rng is None else rng
        floor = rng.choice(list(candidates))
        points = rng.sample(candidates[floor], count)
        result = dict(type=quest_type, level=quest_id, id=quest_id,
            target_floor=floor + 1, points=[list(p) for p in points], investigated_points=[],
            progress=0, required_count=count, completed=False,
            reward=self.quest_data['rewards'][quest_type][str(quest_id)])
        if quest_type == 'hunt':
            source = floor if 'enemy_ids' in self.dungeon.settings['floors'][floor] else floor - 1
            profile = self.dungeon.settings['floors'][source]
            result['hunt_source_floor'] = source + 1
            result['hunt_enemy_id'] = rng.choices(profile['enemy_ids'], profile['weights'])[0]
        result['flavor_id'] = self.choose_flavor(quest_type, quest_id)
        return result

    def activate_quest(self, quest):
        if self.active_quest:
            raise ValueError(self.message('already_active'))
        # Accept the displayed floor and points exactly, or refuse the offer.
        # Do not reroll to another floor if a preview has become invalid.
        valid = spawn_candidates(self.dungeon, quest['target_floor'] - 1)
        points = [tuple(p) for p in quest['points']]
        if (len(valid) < quest['required_count'] or
            len(set(points)) != quest['required_count'] or
            not set(points) <= set(valid)):
            log_spawn_failure(quest['type'], quest['level'], quest['target_floor'] - 1,
                              quest['required_count'], len(valid))
            raise ValueError('安全なQUEST候補地点が足りません。')
        self.active_quest = quest
        self.completion_ready = False
        self.last_flavor_id = quest['flavor_id']
        self.decline_preview()
        return self.message('accepted')

    def accept(self, quest_id, debug=False, quest_type='explore'):
        # Direct acceptance remains available to existing debug/test callers.
        return self.activate_quest(self.make_quest(quest_id, debug, quest_type))

    def preview_quest(self, level, quest_type):
        # The modal UI cannot play while this offer is shown. Generate with a
        # copy, then commit its RNG state only when the player accepts the offer.
        rng = Random()
        rng.setstate(self.session.rng.getstate())
        quest = self.make_quest(level, quest_type=quest_type, rng=rng)
        self.pending_quest, self.pending_quest_rng_state = quest, rng.getstate()
        return quest

    def accept_preview(self):
        if self.active_quest:
            raise ValueError(self.message('already_active'))
        if self.pending_quest is None:
            raise ValueError('確認中の依頼がありません。')
        rng_state = self.pending_quest_rng_state
        message = self.activate_quest(self.pending_quest)
        self.session.rng.setstate(rng_state)
        return message

    def decline_preview(self):
        self.pending_quest = self.pending_quest_rng_state = None

    def hint(self):
        return self.message('hint') if self.active and not self.surveyed and self.target[0] == self.dungeon.floor else ''

    def visible_points(self):
        q = self.active_quest
        if not q or q['completed'] or q['target_floor'] != self.dungeon.floor + 1:
            return []
        return [p for p in q['points'] if p not in q['investigated_points']]

    def hunt_here(self):
        q = self.active_quest
        return bool(q and q['type'] == 'hunt' and [self.dungeon.x, self.dungeon.y] in self.visible_points())

    def investigate(self):
        q = self.active_quest
        point = [self.dungeon.x, self.dungeon.y]
        if not q or q['type'] == 'hunt' or point not in self.visible_points():
            return []
        q['investigated_points'].append(point)
        q['progress'] = len(q['investigated_points'])
        q['completed'] = q['progress'] == q['required_count']
        return [self.message(q['type'])] + ([self.message('objective')] if q['completed'] else [])

    def make_hunt_enemy(self):
        q = self.active_quest
        if not self.hunt_here():
            raise ValueError('討伐対象はいません。')
        profile = self.dungeon.settings['floors'][q['hunt_source_floor'] - 1]
        row = self.dungeon.enemies[q['hunt_enemy_id']]
        bonus = self.quest_data['hunt']
        return [Enemy.from_definition(row,
                      max_hp=max(1, round(row['max_hp'] * profile['hp_scale'] * bonus['hp_multiplier'])),
                      strength=max(1, round(row['str'] * profile['power_scale']) + bonus['str_bonus']),
                      intellect=max(1, round(row['int'] * profile['power_scale'])),
                      defense=row.get('defense', 0) + bonus['def_bonus'])]

    def hunt_victory(self):
        if not self.hunt_here():
            raise ValueError('討伐対象はいません。')
        self.surveyed = True
        return [self.message('hunt'), self.message('objective')]

    def return_to_camp(self, survived, defer_completion=False):
        if not survived:
            was_surveyed = bool(self.active and self.active['progress'])
            self.reset_progress()
            return [self.message('death')] if was_surveyed else []
        if not self.active or not self.surveyed:
            self.completion_ready = False
            return []
        self.completion_ready = True
        return [] if defer_completion else self.finalize_quest_completion()

    def finalize_quest_completion(self):
        """Pay and record one safely returned contract, once, after its thanks."""
        if not self.completion_ready or not self.active or not self.surveyed:
            return []
        q = self.active_quest
        message = self.message('complete')
        reward = self.active["reward"]
        self.session.treasure.banked += reward
        self.quest_clear_counts[q['type']] += 1
        flavor_id = q.get('flavor_id')
        if (flavor_id in QUEST_COMPLETION_IDS[q['type']] and
            self.quest_flavor()['id'] == flavor_id and
            flavor_id not in self.completed_quest_ids):
            self.completed_quest_ids.append(flavor_id)
        self.completed.add(self.active["id"])
        self.active_quest = None
        self.completion_ready = False
        return [message]

    def quest_record(self):
        """Fixed denominators; ignore stale/default IDs in future loaded records."""
        done = set(self.completed_quest_ids)
        rows = {}
        for kind, ids in QUEST_COMPLETION_IDS.items():
            count = len(done.intersection(ids))
            rows[kind] = dict(clears=self.quest_clear_counts[kind], completed=count,
                              total=len(ids), percent=count * 100 // len(ids))
        count = sum(row['completed'] for row in rows.values())
        rows['total'] = dict(completed=count, total=QUEST_COMPLETION_TOTAL,
                             percent=count * 100 // QUEST_COMPLETION_TOTAL)
        return rows

    def damage(self, amount):
        for actor in self.session.party:
            if actor.alive:
                actor.hp = max(1, actor.hp - amount)
        return [f"全員HP -{amount} (最低1)"]

    def heal(self, amount, everyone=True):
        living = [c for c in self.session.party if c.alive]
        if not everyone and living:
            living = [min(living, key=lambda c: c.hp / c.max_hp)]
        recovered = 0
        for c in living:
            gain = c.max_hp - c.hp if amount is None else min(amount, c.max_hp - c.hp)
            c.hp += gain
            recovered += gain
        return [f"{'全員' if everyone else living[0].name if living else '対象なし'} HP回復 合計{recovered}"]

    def chest_effect(self, reward):
        kind = reward["kind"]
        if kind == "TRAP":
            return ["宝箱の罠!"] + self.damage(reward["amount"])
        if kind == "SKILL_CHANCE":
            if self.session.rng.random() >= reward["chance"]:
                return ["古い技の記録……閃かなかった"]
            actor = self.session.rng.choice(self.session.party)
            messages = spark(actor, self.session.skills, self.session.settings, self.session.rng,
                             discovered=self.session.discovered_skills)
            actor.history.extend("宝箱: " + line for line in messages)
            self.session.field_pending = bool(self.session.pending_replacements)
            return messages
        return []

